import 'package:flutter/material.dart';class HolographicNumber extends StatelessWidget{final String value;final String? unit;final Color color;final double fontSize;const HolographicNumber({super.key,required this.value,this.unit,this.color=Colors.white,this.fontSize=76});@override Widget build(BuildContext c)=>Column(mainAxisSize:MainAxisSize.min,children:[ShaderMask(shaderCallback:(r)=>LinearGradient(colors:[Colors.white,color,Colors.white]).createShader(r),blendMode:BlendMode.srcIn,child:Text(value,style:TextStyle(fontSize:fontSize,fontWeight:FontWeight.w900,shadows:[Shadow(color:color.withOpacity(.8),blurRadius:18),Shadow(color:color.withOpacity(.4),blurRadius:40)]))),if(unit!=null)Text(unit!,style:TextStyle(color:Colors.white.withOpacity(.65),fontSize:15))]);}